\uline{Remarque}

Compte tenu des relations (149) (150)
\[
AD-BC=1,\qquad \unsure{A|C}+D-B=1,
\]
et du fait que $D$ est inv., les matrices $\xi$ sont entièrement déterminées par les coeff $B,D$ --- les couples $(\xi,\eta)$ de matrices $\in\mathrm{Sl}(2,\widehat{\mathbb Z})$, satisfaisant
\[
\tag{156}
\left\{\begin{gathered}
\xi\rho(\xi)\rho^2(\xi)=1,\quad
\eta\sigma_\infty(\eta)=1,\quad
\xi=\eta\ell_1^\nu
\qquad(\nu\in\widehat{\mathbb Z}\ \text{\unsure{convenant}})\\
\xi\equiv1\quad(2),\qquad\eta\equiv1\quad(2)
\end{gathered}\right.
\]

\margin{Bien sûr, l'introduction des congruences ici est \unsure{tout à fait} accessoire --- l'énoncé algébrique \unsure{est indépendant} de telles conditions...}

sont en correspondance biunivoque avec les couples $(B,D)$, $B\in\widehat{\mathbb Z}$, $D\in\widehat{\mathbb Z}^{*}$, \inserted{$B\equiv0\ (2)$}, dont on déduit
\[
\xi=\begin{pmatrix}A&B\\C&D\end{pmatrix},\qquad
\eta=\begin{pmatrix}R&S\\T&U\end{pmatrix},\qquad
\text{et }\nu\in\widehat{\mathbb Z}\text{ par}
\]
\[
\tag{157}
\begin{aligned}
C&=B-D+1,\qquad
A=\frac{1+BC}{D}=\frac1D(1+B^2-BD+B)\\
&&\inserted{{}=\mu(1+B+B^2)-B}
\end{aligned}
\]
\[
\tag{158}
\mu=\frac1D,\qquad\nu=\frac{\mu-1}{2},
\]
\deleted{\unsure{(159)}}
\[
\eta=\xi\ell_1^{-\nu}
=\begin{pmatrix}A&B\\C&D\end{pmatrix}
\begin{pmatrix}1&0\\-2\nu&1\end{pmatrix}
=\begin{pmatrix}A-2\nu B&B\\C-2\nu D&D\end{pmatrix}
\qquad\text{i.e.}
\]

\margin{on a normalisé le signe de $\eta$ comme \unsure{dit} dans (156)}

\[
\tag{159}
\text{i.e.}\quad
\unsure{U}=D,\quad S=\unsure{T}=B,\quad
R=A-2\nu B=\mu(1+B^2)=\frac{1+B^2}{D}
\]

Posons (comparer p.~\unsure{398'} (78))
\[
\tag{160}
\underline u_{\xi\deleted{\unsure{,\eta}}}
=\mu\begin{pmatrix}1&B\\0&D\end{pmatrix}
=\begin{pmatrix}\mu&\mu B\\0&1\end{pmatrix}
=\begin{pmatrix}\dfrac1D&B/D\\0&1\end{pmatrix}
\in\mathrm{Gl}(2,\widehat{\mathbb Z})
\]

\margin{\deleted{pour le moment on \unsure{dispose} d'un élément $\xi$ de $\unsure{\widetilde{\widehat{\Pi}}_{0,3}}$, \unsure{qui est déterminé|$\xi$ est déterminé par} comme élément de $\mathrm{Sl}(2,\widehat{\mathbb Z})'$ \unsure{ou dans|ou de} $\mathrm{Sl}(2,\widehat{\mathbb Z})$ \uuline{au signe près}}}

de sorte que la connaissance de $\underline u_\xi$ équivaut à celle \inserted{de $B$ et $D$, i.e. à celle} de $\xi\in\mathrm{Sl}(2,\widehat{\mathbb Z})$, ou encore à celle des couples $(\xi,\eta)$ ($\eta$ normalisé par $\eta=+\xi\ell_1^{-\nu}$). (Dans loc. cit. cet élément était noté $u_{\alpha,\beta}$... mais il ne dépend que de $\xi\in\widehat{\Pi}_{0,3}$, et $\overline{\mathrm m}$ seulement de $\underline\xi\in\mathrm{Sl}(2,\widehat{\mathbb Z})$ --- et sa connaissance équivaut à celle de $\underline\xi\in\mathrm{Sl}(2,\widehat{\mathbb Z})$ ---)

\margin{\uline{NB} On déduit $\xi,\eta$ de la connaissance de $\underline u$ par les formules
\deleted{\illegible{1}}
\[
\tag{161}
\left\{\begin{aligned}
\underline u\cdot{}^t\underline u&=\mu\eta\\
\mu&=\det\underline u
\end{aligned}\right.
\]
d'où
\[
\tag{162}
\left\{\begin{aligned}
\eta&=\mu^{-1}\underline u\cdot{}^t\underline u=\mu^{-1}\unsure{,}\\
\xi&=\eta\ell_1^{-\nu}=\mu^{-1}(\underline u\cdot{}^t\underline u)\ell_1^{-\nu}
\end{aligned}\right.
\]
}

