\[
\tau_\infty^{\prime\alpha_3}\widehat{\varphi}(f_\infty)\alpha=\rho^j
\qquad\text{for }j\in\mathbb Z/3\mathbb Z\ \unsure{\text{suitable}}
\quad\text{(well determined)}.
\]
We make it explicit by \uline{using} the value of $f_\infty$
\[
f_\infty^{-1}=g\rho(g)\rho^2(f_0^{-1})
=g\rho(g)=\rho^2(g)^{-1}=\rho^{-1}(\xi^{-1}),
\]
\inserted{N.B. here $\left\{\begin{gathered}f_0=f=1\\g=\xi=\alpha\rho(\alpha)^{-1}\end{gathered}\right.$}
thus the relation \deleted{\illegible{2}} becomes
\[
\tau_\infty^{\prime\alpha_3}\widehat{\varphi}\bigl(\rho^{-1}(\xi)\bigr)\alpha=\rho^j
\]
i.e., \deleted{by applying $\tau_\infty^{\prime\alpha_3}$ \unsure{to the}}
\[
\widehat{\varphi}\bigl(\rho^{-1}(\xi)\bigr)
=\underbrace{\tau_\infty^{\prime\alpha_3}\rho^j}_{\underbrace{\tau_\infty^{\prime\alpha_3}(\rho^j)}\tau_\infty^{\prime\alpha_3}}\alpha^{-1}
\LMcancelledtag{\deleted{\unsure{44|43}}}
\]
or also
\deleted{\[
\widehat{\varphi}\bigl(\rho^{-1}(\xi^{-1})\bigr)=\alpha\rho^{-j}\tau_\infty^{\prime\alpha_3}.
\tag{\unsure{44 bis|43 bis}}
\]}
since $\tau'_\infty(\rho)=\rho^{-1}$ thus
$\tau_\infty^{\prime\alpha_3}(\rho^j)=\rho^{(-1)^{\alpha_3}j}=\rho^{j'}$
\[
\widehat{\varphi}\bigl(\rho^{-1}(\xi)\bigr)=\rho^{j'}\tau_\infty^{\prime\alpha_3}\alpha^{-1}
\tag{44}
\]
where $\alpha_3=\alpha_3(\mu)\in\mathbb Z/2\mathbb Z$ defined by $(-1)^{\alpha_3}\equiv\mu\ (3)$ and $j'\in\mathbb Z/3\mathbb Z$ (well determined).

We shall transform this relation a little further, by writing
